// The drawings expected below come from elkjs 0.12.1, on nodes as wide and as
// high as routed makes them.

// routed lays spec out from left to right, with nodes of several sizes.
func routed(spec string) Result {
	g := layered(spec)
	widths := []float64{30, 52, 18, 70, 41}
	heights := []float64{45, 30, 5, 62, 14}
	for _, n := range nodes(g) {
		if n.Type == typeNormal {
			i := int(n.ID[0]) % len(heights)
			n.Size = Vec{widths[i], heights[i]}
		}
	}
	for _, step := range []func(*Graph){
		sortByModelOrder, minimizeCrossings, positionPorts, nodeMargins, placeNodes,
		measureLayers, routeEdges, joinLongEdges, restoreReversed, collectNodes,
	} {
		step(g)
	}
	return export(g)
}

// drawing writes r like "172x140 30,86 70,86 | 30,81 50,81", edge by edge.
func drawing(r Result) string {
	number := func(v float64) string { return strconv.FormatFloat(v, 'f', -1, 64) }
	lines := make([]string, len(r.Edges))
	for i, e := range r.Edges {
		points := make([]string, len(e.Points))
		for j, p := range e.Points {
			points[j] = number(p.X) + "," + number(p.Y)
		}
		lines[i] = strings.Join(points, " ")
	}
	return fmt.Sprintf("%sx%s %s", number(r.Width), number(r.Height), strings.Join(lines, " | "))
}

